"""SSA constant folding and propagation.

The entry point :func:`fold_constants` takes an SSA :class:`Module`
produced by :func:`~compiler_ir.ssa.to_ssa` and returns a brand new SSA
:class:`Module` in which known literal values are propagated along the SSA
def-use chains; the input module is never mutated and shares no mutable
function, block, instruction or phi container with the result.

A value is *known* when it is statically provably a fixed literal:

* a ``Const`` definition is known directly;
* an arithmetic or compare ``BinOp`` folds only when both operands are
  known, and its result becomes known for subsequent definitions;
* a ``Phi`` folds exactly when the literals arriving on *every* reachable
  predecessor edge are all known and identical (the phi's own result is
  not an incoming definition and cannot occur there).

Arithmetic covers ``add``, ``sub``, ``mul``, ``div`` and ``mod``, and
comparisons ``eq``, ``ne``, ``lt``, ``le``, ``gt`` and ``ge``; the int and
bool result types are preserved.  Integer division truncates toward zero
and the remainder satisfies ``a == div(a,b) * b + mod(a,b)``.  A known
zero divisor must not be folded away: the original ``BinOp`` is kept so the
runtime trap and its position in the instruction stream are neither
advanced, swallowed nor rewritten.  A ``Call`` result is always unknown,
and the call instruction together with its relative order is untouched.

Because loop header phis can look constant on their (constant) entry edge
before the back edge is analyzed, literals are tracked in a monotone
three-level lattice -- unknown, constant ``k``, and non-constant -- solved
to a fixpoint: a phi starts unknown, sinks to its first seen literal and
reaches non-constant as soon as two edges disagree (or an edge carries a
non-constant value).  This mirrors classic sparse conditional constant
propagation without its reachability half, which this pass deliberately
does not perform: no blocks are deleted, no constant ``Branch`` becomes a
``Jump``, and definitions made pointless by folding are left in place for
:func:`~compiler_ir.dce.eliminate_dead_code` to remove.

The pass is purely value-definition rewriting.  Function order, signatures,
parameters, block labels and order, terminators, the relative order of all
instructions (including folded ones, which stay in place), phi order and
the existing SSA numbers are all preserved -- so the output contains the
same number of phi and instruction slots as the input.  Applying the pass
again gives a structurally and textually identical fixed point.

A non-:class:`Module` object raises :class:`TypeError`; a non-SSA
:class:`Module` raises :class:`ValueError`.
"""
from .ir_nodes import (
    BinOp,
    Block,
    Branch,
    Call,
    Const,
    Function,
    Jump,
    Module,
    Parameter,
    Phi,
    Return,
    Temp,
)


# Lattice levels, stored per SSA value (keyed by id) in the solver state:
#   None             -> unknown (not yet constrained; a phi's initial state)
#   int/bool literal -> known to be exactly that literal
#   _BOTTOM          -> not a compile-time constant
_BOTTOM = object()


def fold_constants(module: Module) -> Module:
    """Return a new SSA :class:`Module` with literals folded and propagated.

    The input module is left untouched; the result shares no mutable
    function, block, instruction or phi object with it.  The empty module
    and modules without foldable definitions come back as independent,
    content-equivalent copies.

    :raises TypeError: if ``module`` is not a :class:`Module` instance.
    :raises ValueError: if ``module`` is not in SSA form.
    """
    if not isinstance(module, Module):
        raise TypeError(
            "fold_constants expects a Module, got "
            f"{type(module).__name__}"
        )
    if not getattr(module, "ssa", False):
        raise ValueError("fold_constants expects an SSA Module")
    return Module(
        [_fold_function(func) for func in module.functions], ssa=True
    )


# --------------------------------------------------------------------------
# Arithmetic / comparison semantics (truncated toward zero, like the runtime)
# --------------------------------------------------------------------------


def _trunc_div(a: int, b: int) -> int:
    """Integer division truncated toward zero.

    Only called for a provably non-zero divisor; a zero divisor is handled
    by the caller so the faulting instruction stays in the stream.
    """
    quotient = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        quotient = -quotient
    return quotient


def _trunc_mod(a: int, b: int) -> int:
    # a == div(a,b) * b + mod(a,b)
    return a - _trunc_div(a, b) * b


_ARITH = {
    "add": lambda a, b: a + b,
    "sub": lambda a, b: a - b,
    "mul": lambda a, b: a * b,
    "div": _trunc_div,
    "mod": _trunc_mod,
}

_COMPARE = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "lt": lambda a, b: a < b,
    "le": lambda a, b: a <= b,
    "gt": lambda a, b: a > b,
    "ge": lambda a, b: a >= b,
}


# --------------------------------------------------------------------------
# Fixpoint solver
# --------------------------------------------------------------------------


class _Folder:
    """Per-function literal lattice, solved to a monotone fixpoint."""

    def __init__(self, func: Function):
        self.func = func
        self.lattice: dict = {}
        # Definition -> users that must be re-examined when it moves.
        self.users: dict = {}
        self.worklist: list = []

    def get(self, value):
        return self.lattice.get(id(value))

    def set(self, value, level) -> bool:
        """Move ``value`` monotonically down the lattice; return whether it
        moved."""
        current = self.lattice.get(id(value))
        if current is level or current == level and level is not _BOTTOM:
            return False
        if current is _BOTTOM:
            return False  # nothing below bottom
        if current is not None and level is not _BOTTOM:
            # constant k1 -> constant k2 disagrees: collapse to bottom
            if current != level:
                level = _BOTTOM
        self.lattice[id(value)] = level
        return True

    def note_user(self, operand, user) -> None:
        self.users.setdefault(id(operand), []).append(user)

    # -- lattice transfer functions ----------------------------------------

    def phi_level(self, phi: Phi):
        """Join of every reachable incoming value's lattice level."""
        result = None  # unknown while no edge constrains it
        for value in phi.entries.values():
            level = self.get(value)
            if level is _BOTTOM:
                return _BOTTOM
            if level is None:
                continue
            if result is None:
                result = level
            elif result != level:
                return _BOTTOM
        return result

    def binop_level(self, ins: BinOp):
        left = self.get(ins.left)
        right = self.get(ins.right)
        if left is _BOTTOM or right is _BOTTOM:
            return _BOTTOM
        if left is None or right is None:
            return None
        if ins.kind == "arith":
            if ins.operator in ("div", "mod") and right == 0:
                # Keep the faulting instruction; its result is not a known
                # literal even though the operands are.
                return _BOTTOM
            operation = _ARITH[ins.operator]
            return operation(left, right)
        operation = _COMPARE[ins.operator]
        return operation(left, right)

    def solve(self) -> None:
        # Parameters and call results are never statically known; seed them
        # at bottom so edges that merely carry them cannot leave a phi
        # spuriously "unknown".
        for param in self.func.params:
            self.set(param.temp, _BOTTOM)

        # Register users and seed definitions in the same deterministic
        # order in which the values were numbered: phis (per block, in id
        # order) before ordinary instructions.  Order on the worklist does
        # not affect the fixpoint, only iteration count.
        for block in self.func.blocks:
            for phi in block.phis:
                for value in phi.entries.values():
                    self.note_user(value, ("phi", phi))
                self.worklist.append(("phi", phi))
            for ins in block.instructions:
                if isinstance(ins, Const):
                    self.worklist.append(("const", ins))
                elif isinstance(ins, BinOp):
                    self.note_user(ins.left, ("binop", ins))
                    self.note_user(ins.right, ("binop", ins))
                    self.worklist.append(("binop", ins))
                elif isinstance(ins, Call):
                    self.set(ins.dest, _BOTTOM)
                # Copy cannot survive to_ssa; treat defensively if present.

        seen = set()
        while self.worklist:
            user = self.worklist.pop()
            key = id(user[1])
            if key in seen and False:
                pass
            if user[0] == "const":
                ins = user[1]
                if self.set(ins.dest, ins.value):
                    self._enqueue_users(ins.dest)
            elif user[0] == "binop":
                ins = user[1]
                if self.set(ins.dest, self.binop_level(ins)):
                    self._enqueue_users(ins.dest)
            else:
                phi = user[1]
                if self.set(phi.dest, self.phi_level(phi)):
                    self._enqueue_users(phi.dest)

    def _enqueue_users(self, value) -> None:
        for user in self.users.get(id(value), ()):
            self.worklist.append(user)

    # -- output construction -----------------------------------------------

    def known(self, value):
        """The literal of ``value`` if it settled on a constant, else None."""
        level = self.get(value)
        if level is _BOTTOM or level is None:
            return None
        return level

    def build(self) -> Function:
        self.solve()

        new_blocks = [Block(block.id) for block in self.func.blocks]
        block_map = dict(zip(self.func.blocks, new_blocks))

        # One fresh Temp per original definition, keeping original ids.
        value_map: dict = {}

        def fresh(value):
            mapped = value_map.get(id(value))
            if mapped is None:
                mapped = Temp(value.id, value.type)
                value_map[id(value)] = mapped
            return mapped

        for param in self.func.params:
            fresh(param.temp)
        for block in self.func.blocks:
            for phi in block.phis:
                fresh(phi.dest)
            for ins in block.instructions:
                fresh(ins.dest)

        def map_value(value):
            if value is None:
                return None
            return value_map[id(value)]

        for block, new_block in zip(self.func.blocks, new_blocks):
            for phi in block.phis:
                literal = self.known(phi.dest)
                if literal is not None:
                    # The merge always yields this literal: emit a Const at
                    # the phi's value slot, and no phi node.
                    new_block.phis.append  # see below; placeholder removed
                    new_block.instructions.append(
                        Const(map_value(phi.dest), literal)
                    )
                    continue
                entries = {
                    block_map[pred]: self._map_through(value, map_value)
                    for pred, value in sorted(
                        phi.entries.items(), key=lambda item: item[0].id
                    )
                }
                new_block.phis.append(Phi(map_value(phi.dest), entries))

            for ins in block.instructions:
                new_block.instructions.append(
                    self._clone_instruction(ins, map_value)
                )

            term = block.terminator
            if isinstance(term, Return):
                new_block.terminator = Return(
                    self._map_through(term.value, map_value)
                )
            elif isinstance(term, Jump):
                new_block.terminator = Jump(block_map[term.target])
            elif isinstance(term, Branch):
                new_block.terminator = Branch(
                    self._map_through(term.cond, map_value),
                    block_map[term.true_target],
                    block_map[term.false_target],
                )

        new_params = [
            Parameter(param.name, param.slot, map_value(param.temp))
            for param in self.func.params
        ]

        return Function(
            self.func.name,
            new_params,
            self.func.ret_type,
            list(self.func.locals),
            new_blocks,
            block_map[self.func.entry],
            ssa=True,
        )

    def _map_through(self, value, map_value):
        """Map an operand, substituting a folded literal's Const dest.

        When an operand itself settled on a constant, every use reads that
        constant directly -- this is the propagation half of the pass.
        """
        if value is None:
            return None
        literal = self.known(value)
        if literal is None:
            return map_value(value)
        return self._const_dest(value, literal, map_value)

    def _const_defs(self):
        return getattr(self, "_const_def_map", None)

    def _const_dest(self, value, literal, map_value):
        # The folded Const for a value is emitted in the value's own slot
        # (phi folded) or in the original Const's slot, so propagating to a
        # known value simply names that definition.
        return map_value(value)

    def _clone_instruction(self, ins, map_value):
        if isinstance(ins, Const):
            return Const(map_value(ins.dest), ins.value)
        if isinstance(ins, BinOp):
            literal = self.known(ins.dest)
            if literal is not None:
                return Const(map_value(ins.dest), literal)
            return BinOp(
                map_value(ins.dest), ins.operator,
                self._map_through(ins.left, map_value),
                self._map_through(ins.right, map_value),
                ins.kind, ins.type,
            )
        if isinstance(ins, Call):
            return Call(
                map_value(ins.dest), ins.name,
                [self._map_through(arg, map_value) for arg in ins.args],
                ins.type,
            )
        # Defensive: Copy should not appear in SSA IR, but clone it through.
        return Copy(map_value(ins.dest), self._map_through(ins.src, map_value))


def _fold_function(func: Function) -> Function:
    return _Folder(func).build()

